import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"安裝 Jan","description":"使用 Jan 桌面應用加載本地模型，並開啟 API 供 MiniTavern 局域網連接。","frontmatter":{"title":"安裝 Jan","description":"使用 Jan 桌面應用加載本地模型，並開啟 API 供 MiniTavern 局域網連接。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 Jan · MiniTavern Docs"}],["meta",{"property":"og:description","content":"使用 Jan 桌面應用加載本地模型，並開啟 API 供 MiniTavern 局域網連接。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/jan/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/jan/install"}]]},"headers":[],"relativePath":"zh-TW/jan/install.md","filePath":"zh-TW/jan/install.md","lastUpdated":1787224147000}'),i={name:"zh-TW/jan/install.md"};function l(o,a,s,h,c,d){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="jan" tabindex="-1">Jan <a class="header-anchor" href="#jan" aria-label="Permalink to &quot;Jan&quot;">​</a></h1><p><a href="https://jan.ai/" target="_blank" rel="noreferrer">Jan</a> 是偏「本地助手」的桌面應用，可下載/加載模型，並在設置中開啟 <strong>API Server</strong>（OpenAI 兼容），從而被 MiniTavern 連接。</p><h2 id="步驟概要" tabindex="-1">步驟概要 <a class="header-anchor" href="#步驟概要" aria-label="Permalink to &quot;步驟概要&quot;">​</a></h2><ol><li>安裝並打開 Jan，在應用內下載或導入模型。</li><li>打開設置中的 <strong>Local API</strong> / <strong>API Server</strong>（名稱以當前版本為準）。</li><li>允許局域網訪問（若有開關），記下 <strong>端口</strong>。</li><li>本機訪問 <code>http://127.0.0.1:端口/v1/models</code> 確認列表。</li><li>手機填寫 <code>http://YOUR_PC_IP:端口/v1</code>，模型名與列表一致。</li></ol><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>Jan 版本迭代較快，菜單路徑以官方文檔為準。</li><li>連不上時先確認服務已 Start，再查防火牆與 IP（見 <a href="/ultra_guides/zh-TW/troubleshoot">排錯</a>）。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中配置</a> · <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a></p>',8)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
